func longestStrChain(words []string) int {
    sort.Slice(words, func(i, j int) bool {
        return len(words[i]) < len(words[j])
    })

    n := len(words)
    dp := make([]int, n)
    for i := range dp {
        dp[i] = 1
    }

    isPred := func(w1, w2 string) bool {
        i := 0
        for _, c := range w2 {
            if i == len(w1) {
                return true
            }
            if rune(w1[i]) == c {
                i++
            }
        }
        return i == len(w1)
    }

    for i := 1; i < n; i++ {
        for j := i - 1; j >= 0; j-- {
            if len(words[j])+1 < len(words[i]) {
                break
            }
            if len(words[j])+1 > len(words[i]) || !isPred(words[j], words[i]) {
                continue
            }
            if dp[j]+1 > dp[i] {
                dp[i] = dp[j] + 1
            }
        }
    }

    maxChain := 0
    for _, v := range dp {
        if v > maxChain {
            maxChain = v
        }
    }
    return maxChain
