impl Solution {
    pub fn longest_str_chain(words: Vec<String>) -> i32 {
        let mut words = words;
        words.sort_by_key(|w| w.len());
        let n = words.len();
        let mut dp = vec![1i32; n];

        fn is_pred(w1: &str, w2: &str) -> bool {
