        for i in 1..n {
            for j in (0..i).rev() {
                if words[j].len() + 1 < words[i].len() {
                    break;
                }
                if words[j].len() + 1 > words[i].len()
                    || !is_pred(&words[j], &words[i])
                {
                    continue;
                }
                dp[i] = dp[i].max(1 + dp[j]);
            }
        }

        *dp.iter().max().unwrap()
    }
}
